import{_ as e,H as t,f as a,i as r}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"모범 사례","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/best-practices.md","filePath":"ko/guide/best-practices.md"}'),n={name:"ko/guide/best-practices.md"};function s(i,o,d,c,l,p){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="모범-사례" tabindex="-1">모범 사례 <a class="header-anchor" href="#모범-사례" aria-label="Permalink to &quot;모범 사례&quot;">​</a></h1><h2 id="명세" tabindex="-1">명세 <a class="header-anchor" href="#명세" aria-label="Permalink to &quot;명세&quot;">​</a></h2><p><strong>선언적으로 작성하라, 서술적으로 말고.</strong> <code>contract:</code>, <code>invariant:</code>, <code>test:</code>, <code>failure:</code> 같은 섹션을 사용하라. 번호 매긴 단계나 산문은 사용하지 않는다. 에이전트는 빠르게 읽고 정확한 선언을 따른다.</p><p><strong>구현에 영향을 미치는 결정만 닫아라.</strong> <code>plan</code>에 넘기기 전에 해결할 것: 계약, 데이터 형태, 실패 모드, 테스트 기준. 철학적 논쟁과 &quot;있으면 좋은&quot; 기능은 <code>deferred</code> 또는 <code>Working notes</code>에 남겨라.</p><p><strong>코드는 경로로 참조하고, 절대 붙여넣지 않는다.</strong> 명세는 무엇을 만들지에 대한 결정이지, 어떻게 만드는지에 대한 안내가 아니다.</p><h2 id="계획" tabindex="-1">계획 <a class="header-anchor" href="#계획" aria-label="Permalink to &quot;계획&quot;">​</a></h2><p><strong>작업은 30~60분.</strong> 에이전트가 추론할 수 있을 만큼 원자적으로. 너무 크면 가시성을 잃고, 너무 작으면 오버헤드가 흐름을 죽인다.</p><p><strong>수락 조건은 실행 가능해야 한다.</strong> 각 작업의 수락 조건은 CI/사람이 검증할 수 있는 것이어야 한다: 테스트 이름, 명령어, 또는 스크립트. 모호하지 않고, 이상론적이지 않게.</p><p><strong><code>[parallel]</code>은 진정으로 독립적일 때만 표시.</strong> 공유 상태, 오류 처리, 또는 닫히지 않은 계약 → 작업은 병렬이 아니다. 과도한 표시는 깨진 병합으로 이어진다.</p><h2 id="git-워크플로" tabindex="-1">Git 워크플로 <a class="header-anchor" href="#git-워크플로" aria-label="Permalink to &quot;Git 워크플로&quot;">​</a></h2><p><strong>RED-GREEN-refactor 사이클마다 한 번 커밋.</strong> 생각을 히스토리에 남긴다. 나중에 디버깅할 때 도움이 된다.</p><p><strong>각 사이클 후 문서를 동기화.</strong> 커밋 직전. 기다리면 무엇을 바꿨는지, 왜 바꿨는지 잊어버린다.</p><p><strong>설명적인 브랜치 이름을 사용.</strong> <code>feature1</code>이 아닌 <code>feat/oauth-github</code>. 여러 worktree가 있을 때 탐색하기 쉽다.</p><h2 id="대규모-프로젝트" tabindex="-1">대규모 프로젝트 <a class="header-anchor" href="#대규모-프로젝트" aria-label="Permalink to &quot;대규모 프로젝트&quot;">​</a></h2><p><strong>마일스톤이 ≥3개면 로드맵을 사용.</strong> 처음부터 모두 계획하려 하지 마라. 현재 것만 <code>plan</code>하고, 배우면서 스텁을 업데이트하라.</p><p><strong>현재 마일스톤을 명확하게 표시.</strong> M1에 <code>← 지금 상세 계획</code>으로 의도를 나타낸다. ship 후, M2를 계획하기 전에 마커를 옮긴다.</p><p><strong>M1 후 마일스톤을 수정할 것을 예상하라.</strong> 첫 번째 마일스톤이 나머지 비용을 가르쳐 준다. 그것이 핵심이다.</p><h2 id="디버깅" tabindex="-1">디버깅 <a class="header-anchor" href="#디버깅" aria-label="Permalink to &quot;디버깅&quot;">​</a></h2><p><strong>먼저 고립시키고, 다음에 가설을 세워라.</strong> 최소 재현 지점까지 좁혀라. 증상이 사라질 때까지 코드를 제거하라. 그 후에 &quot;왜&quot;를 물어라.</p><p><strong>한 번에 하나의 변수만 바꿔라.</strong> 병렬 가설은 매력적이지만 어떤 변경이 수정했는지 알기 어렵게 만든다.</p><h2 id="테스트" tabindex="-1">테스트 <a class="header-anchor" href="#테스트" aria-label="Permalink to &quot;테스트&quot;">​</a></h2><p><strong>구현이 아닌 계약을 테스트하라.</strong> 계약이 &quot;성공 시 200 반환&quot;이라고 하면, 그것을 테스트한다. &quot;X 함수 호출&quot;이나 &quot;데이터베이스 Y에서 읽기&quot;가 아니다.</p><p><strong>내부 목(mock) 사용 금지.</strong> 외부 경계를 목 처리: HTTP, DB, 파일시스템. 자신의 코드를 목 처리하는 것은 실제 버전이 느리거나 비결정적인 경우에만.</p><h2 id="언제-포기할까" tabindex="-1">언제 포기할까 <a class="header-anchor" href="#언제-포기할까" aria-label="Permalink to &quot;언제 포기할까&quot;">​</a></h2><p><strong>가정이 본질적으로 바뀌면, 멈추고 재탐색하라.</strong> 해결하고 있는 문제가 더 이상 문제가 아니라면 억지로 밀어붙이지 마라. 발견 노트에 시도 이유와 교훈을 기록하라.</p><p><strong>마일스톤 목표가 ≥50% 바뀌면, 설계로 돌아가라.</strong> 계획을 연장하지 마라. 새로운 방향을 인정하고 재시작하라.</p><h2 id="명세-리뷰-통합-평가-spec-review-synthesis" tabindex="-1">명세 리뷰 통합 평가 (Spec Review Synthesis) <a class="header-anchor" href="#명세-리뷰-통합-평가-spec-review-synthesis" aria-label="Permalink to &quot;명세 리뷰 통합 평가 (Spec Review Synthesis)&quot;">​</a></h2><p><strong>리뷰어는 조언을 제공하고 Coordinator가 최종 결정을 내립니다.</strong> 명세 리뷰어는 전용 찰터를 가진 독립 서브에이전트로 작동합니다. 주 에이전트(Coordinator)는 지적 사항을 비판적으로 평가하고, 충돌 해결, 누락 조치를 수행하여 한 번의 패스로 명세서를 수정합니다.</p><h2 id="모델-계층-매핑-model-tier-mapping" tabindex="-1">모델 계층 매핑 (Model Tier Mapping) <a class="header-anchor" href="#모델-계층-매핑-model-tier-mapping" aria-label="Permalink to &quot;모델 계층 매핑 (Model Tier Mapping)&quot;">​</a></h2><p><strong>작업 위험도에 맞춰 모델 능력을 매핑합니다.</strong> 기계적 수정이나 Lint 검사에는 <code>fast</code>, 단일 컴포넌트 구현에는 <code>balanced</code>, 핵심 프로토콜이나 안전 리뷰, 복잡한 상태 머신에는 <code>strongest</code>를 사용합니다. <code>.praxis/model-tiers.yaml</code> 파일에서 설정합니다.</p><h2 id="멀티-모듈-조율-multi-module-coordination" tabindex="-1">멀티 모듈 조율 (Multi-Module Coordination) <a class="header-anchor" href="#멀티-모듈-조율-multi-module-coordination" aria-label="Permalink to &quot;멀티 모듈 조율 (Multi-Module Coordination)&quot;">​</a></h2><p><strong>Coordinator 리포지토리를 하나 명시적으로 지정합니다.</strong> Coordinator가 change-set ID, 모듈 교차 명세 및 워크스페이스 계획을 소유합니다. 각 모듈 명세에 공유 계약을 중복 정의하지 말고 Coordinator 명세를 직접 참조합니다. 커밋은 의존성 순서대로 진행하며 Coordinator가 마지막에 커밋합니다.</p><h2 id="문서-동기화" tabindex="-1">문서 동기화 <a class="header-anchor" href="#문서-동기화" aria-label="Permalink to &quot;문서 동기화&quot;">​</a></h2><p><strong>라이빙 문서는 사실이고, 스테이징 문서는 초안입니다.</strong> <code>ship</code> 이후 명세는 라이빙 문서로 이동합니다. 코드 내 테스트와 주석은 항상 최신 상태를 유지합니다.</p><p><strong>README는 첫 번째 명세서입니다.</strong> 코드와 일치하지 않으면 PR 리뷰를 통과할 수 없습니다.</p>',35)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
